using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync, "search_web",
        "Search the web for information on a topic. Returns a list of relevant results."),
    AIFunctionFactory.Create(researchTools.TakeNote, "take_note",
        "Save a research note for later reference. Use this to record key findings."),
    AIFunctionFactory.Create(researchTools.GetNotes, "get_notes",
        "Retrieve all research notes taken so far."),
};

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research agent. When given a topic:
        1. Search the web for relevant information using the search_web tool.
        2. Take notes on key findings using the take_note tool.
        3. Perform additional searches to fill knowledge gaps.
        4. Once you have enough information, retrieve your notes and provide a comprehensive summary.

        Always cite your sources. Be thorough but concise.
        """,
    tools: tools);

// Get the research topic
string topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    new ChatClientAgentRunOptions
    {
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        },
    });

Console.WriteLine("\n📋 Research Summary:\n");
foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine($"\n📝 Notes taken: {researchTools.NoteCount}");

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine();
    return string.IsNullOrWhiteSpace(topic)
        ? throw new InvalidOperationException("A research topic is required.")
        : topic;
}

