using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;

namespace ResearchAgent;

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
public sealed class ResearchTools
{
    private readonly ILogger<ResearchTools> _logger;
    private readonly HttpClient _httpClient;
    private readonly List<ResearchNote> _notes = [];

    public int NoteCount => _notes.Count;

    public ResearchTools(ILogger<ResearchTools> logger, IHttpClientFactory? httpClientFactory = null)
    {
        _logger = logger;
        _httpClient = httpClientFactory?.CreateClient("WebSearch") ?? new HttpClient();
        _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
            "ResearchAgent/1.0 (compatible; research-bot)");
    }

    /// <summary>
    /// Searches the web for information about a query using a search API.
    /// </summary>
    [Description("Search the web for information on a topic")]
    public async Task<string> SearchWebAsync(
        [Description("The search query")] string query,
        [Description("Maximum number of results to return")] int maxResults = 5)
    {
        _logger.LogInformation("Searching web for: {Query}", query);

        try
        {
            // Use a web search API (configurable via environment)
            var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY");
            var searchEndpoint = Environment.GetEnvironmentVariable("SEARCH_ENDPOINT")
                ?? "https://api.bing.microsoft.com/v7.0/search";

            if (string.IsNullOrEmpty(searchApiKey))
            {
                // Fallback: return simulated results for demonstration
                _logger.LogWarning("SEARCH_API_KEY not set. Returning simulated results.");
                return GetSimulatedResults(query);
            }

            using var request = new HttpRequestMessage(HttpMethod.Get,
                $"{searchEndpoint}?q={Uri.EscapeDataString(query)}&count={maxResults}");
            request.Headers.Add("Ocp-Apim-Subscription-Key", searchApiKey);

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync();
            using var doc = JsonDocument.Parse(content);

            var results = new List<SearchResult>();
            if (doc.RootElement.TryGetProperty("webPages", out var webPages) &&
                webPages.TryGetProperty("value", out var values))
            {
                foreach (var item in values.EnumerateArray().Take(maxResults))
                {
                    results.Add(new SearchResult
                    {
                        Title = item.GetProperty("name").GetString() ?? "",
                        Url = item.GetProperty("url").GetString() ?? "",
                        Snippet = item.GetProperty("snippet").GetString() ?? "",
                    });
                }
            }

            _logger.LogInformation("Found {Count} results for: {Query}", results.Count, query);
            return FormatResults(results);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    /// <summary>
    /// Takes a research note for later summarization.
    /// </summary>
    [Description("Save a research note with a title and content")]
    public string TakeNote(
        [Description("Brief title for the note")] string title,
        [Description("The note content with key findings")] string content,
        [Description("The source URL or reference")] string? source = null)
    {
        var note = new ResearchNote
        {
            Title = title,
            Content = content,
            Source = source,
            Timestamp = DateTimeOffset.UtcNow,
        };

        _notes.Add(note);
        _logger.LogInformation("Note taken: {Title}", title);
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    /// <summary>
    /// Retrieves all research notes taken during this session.
    /// </summary>
    [Description("Retrieve all research notes taken so far")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been taken yet.";
        }

        var formatted = _notes.Select((n, i) =>
            $"[{i + 1}] {n.Title}\n    {n.Content}" +
            (n.Source is not null ? $"\n    Source: {n.Source}" : ""));

        return string.Join("\n\n", formatted);
    }

    private static string FormatResults(List<SearchResult> results)
    {
        if (results.Count == 0)
        {
            return "No results found.";
        }

        var formatted = results.Select((r, i) =>
            $"[{i + 1}] {r.Title}\n    URL: {r.Url}\n    {r.Snippet}");

        return string.Join("\n\n", formatted);
    }

    private static string GetSimulatedResults(string query)
    {
        return $"""
            [Simulated search results for: "{query}"]

            [1] Overview of {query} - Wikipedia
                URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
                A comprehensive overview covering the history, key concepts, and current developments related to {query}.

            [2] Latest Research on {query} - Science Daily
                URL: https://www.sciencedaily.com/search/?keyword={Uri.EscapeDataString(query)}
                Recent scientific findings and breakthroughs in the field of {query}, including peer-reviewed studies.

            [3] {query}: A Practical Guide - Medium
                URL: https://medium.com/topic/{Uri.EscapeDataString(query)}
                An accessible introduction to {query} covering fundamental principles and real-world applications.

            Note: These are simulated results. Set SEARCH_API_KEY environment variable for real web search.
            """;
    }

    private sealed record SearchResult
    {
        public required string Title { get; init; }
        public required string Url { get; init; }
        public required string Snippet { get; init; }
    }

    private sealed record ResearchNote
    {
        public required string Title { get; init; }
        public required string Content { get; init; }
        public string? Source { get; init; }
        public DateTimeOffset Timestamp { get; init; }
    }
}

